import{ENEMY_ROLES}from './enemy-behaviors.js';
import{CHASSIS,chassisBlueprint}from './chassis.js';
import{MISSIONS,missionTuning,campaignRound}from './mission-catalog.js';
import{LANDINGS,profileFor,refitOffer}from './campaign.js';
import{CONTRACTS,FIELD_MODULES}from './sortie-progression.js';
import{debriefMarkup,formatTime}from './sortie-view.js';
import{cleanBuild,EQUIPMENT,ABILITIES,mechStats,buildKey,validBuild}from './core.js?v=41';
import{itemIcon}from './workshop-icons.js?v=41';
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const short=id=>EQUIPMENT[id].name.split(' / ').at(-1);
const TABS=[['operations','Operations'],['loadout','Loadout'],['refits','Refits'],['contracts','Contracts'],['report','Report']];
export const CAMPAIGN_MECHS=Object.values(CHASSIS).map(c=>({label:c.name,role:`${c.size.toUpperCase()} / ${c.role}`,build:cleanBuild(chassisBlueprint(c.id))}));

// Cover, raised platforms and objective sites use the actual playable mission geometry.
function battlefield(spec){
 const round=campaignRound(spec.id),project=(x,y,z=0)=>[410+(x-y)*.145,42+(x+y)*.071-z*.12],point=(x,y,z=0)=>project(x,y,z).map(v=>v.toFixed(1)).join(','),poly=ps=>ps.map(p=>point(...p)).join(' ');
 const block=(o,i)=>{const z=Math.min(o.height||o.z||50,220),x=o.x,y=o.y,w=o.w,h=o.h;return`<g><polygon points="${poly([[x,y+h],[x+w,y+h],[x+w,y+h,z],[x,y+h,z]])}" fill="#242c31"/><polygon points="${poly([[x+w,y],[x+w,y+h],[x+w,y+h,z],[x+w,y,z]])}" fill="#303a40"/><polygon points="${poly([[x,y,z],[x+w,y,z],[x+w,y+h,z],[x,y+h,z]])}" fill="${o.landmark?'#7d6f5c':i%2?'#586361':'#6c7267'}" stroke="#bac4ad" stroke-opacity=".5" stroke-width=".7"/>${o.cargo?`<path d="M${point(x+w*.3,y,z)}L${point(x+w*.3,y+h,z)}M${point(x+w*.65,y,z)}L${point(x+w*.65,y+h,z)}" stroke="#222b29" stroke-width="2"/>`:''}</g>`;};
 const route=round.points.map(p=>point(p.x,p.y,0)).join(' '),entry=project(round.entry.x,round.entry.y);
 return`<svg class="battlefield-scan" viewBox="0 0 820 430" role="img" aria-label="Isometric tactical scan of ${escape(spec.name)}. ${round.points.length} objective sites, cover and insertion zone."><defs><pattern id="scan-grid" width="34" height="34" patternUnits="userSpaceOnUse" patternTransform="matrix(1 .49 -1 .49 410 42)"><path d="M34 0H0V34" fill="none" stroke="#c3d0bf" stroke-opacity=".13" stroke-width="1"/></pattern><radialGradient id="scan-light"><stop stop-color="${spec.color}" stop-opacity=".18"/><stop offset="1" stop-color="${spec.color}" stop-opacity="0"/></radialGradient></defs><ellipse cx="425" cy="245" rx="320" ry="180" fill="url(#scan-light)"/><polygon points="${poly([[0,0],[2600,0],[2600,2300],[0,2300]])}" fill="${spec.floor}" stroke="#7d8e86" stroke-width="1"/><polygon points="${poly([[0,0],[2600,0],[2600,2300],[0,2300]])}" fill="url(#scan-grid)"/>
 <g stroke="#bbc1a9" fill="none" opacity=".16" stroke-width="16"><path d="M${point(230,450)}L${point(2380,450)}M${point(230,1850)}L${point(2380,1850)}M${point(1300,200)}L${point(1300,2080)}"/></g>
 ${spec.theme==='spillway'?`<path d="M${point(250,1000)}L${point(2350,1000)}M${point(250,1100)}L${point(2350,1100)}" stroke="#7acacb" opacity=".6" stroke-width="12"/>`:spec.theme==='rail'?`<g stroke="#9cae9b" opacity=".65" fill="none" stroke-width="2"><path d="M${point(200,400)}L${point(2300,1900)}M${point(250,350)}L${point(2350,1850)}M${point(2100,200)}L${point(400,2100)}M${point(2150,250)}L${point(450,2150)}"/></g>`:spec.theme==='foundry'?`<path d="M${point(250,600)}L${point(2300,600)}M${point(250,1400)}L${point(2300,1400)}" stroke="#f48254" opacity=".5" stroke-width="7"/>`:''}
 <polyline points="${point(round.entry.x,round.entry.y)} ${route}" fill="none" stroke="${spec.color}" stroke-opacity=".7" stroke-width="2" stroke-dasharray="5 7"/>
 ${[...round.platforms.map(p=>({...p,height:p.z})),...round.obstacles.filter(o=>o.cargo||o.landmark)].sort((a,b)=>(a.x+a.y)-(b.x+b.y)).map(block).join('')}
 ${round.points.map((p,i)=>{const [x,y]=project(p.x,p.y,p.z);return`<g><ellipse cx="${x}" cy="${y+7}" rx="28" ry="14" fill="${spec.color}" opacity=".12"/><ellipse cx="${x}" cy="${y+7}" rx="22" ry="11" fill="none" stroke="${spec.color}" stroke-width="1.5"/><path d="M${x} ${y+5}V${y-25}" stroke="${spec.color}" stroke-width="1.5"/><rect x="${x-12}" y="${y-46}" width="24" height="24" fill="${spec.color}"/><text x="${x}" y="${y-29}" text-anchor="middle" fill="#182126" font-size="13" font-weight="700">${i+1}</text></g>`;}).join('')}
 <g><path d="M${entry[0]-10} ${entry[1]+2}l10 -10 10 10 -10 10Z" fill="#a9d6ce"/><text x="${entry[0]}" y="${entry[1]+32}" text-anchor="middle" fill="#cbddd5" font-size="12" letter-spacing="2">INSERTION</text></g><text x="730" y="375" fill="#b4c0b6" font-size="11" letter-spacing="2">N ↗</text></svg>`;
}

export function createCampaignView(root,actions){
 let inspected=0,latest,pending=null,tab='operations';
 root.addEventListener('click',event=>{
  const target=event.target.closest('[data-tab],[data-action],[data-level],[data-contract],[data-refit]');if(!target||target.disabled)return;
  if(target.dataset.tab){tab=target.dataset.tab;render(latest);root.querySelector(`[role="tab"][data-tab="${tab}"]`)?.focus({preventScroll:true});return;}
  if(target.dataset.level!==undefined){inspected=Number(target.dataset.level);render(latest);return;}
  if(target.dataset.contract){actions.contract(target.dataset.contract);return;}
  if(target.dataset.refit){pending={revision:latest.campaign.revision,id:target.dataset.refit};actions.refit(pending);render(latest);return;}
  if(target.dataset.action==='focus'){inspected=Math.min(8,latest.campaign.level);tab='operations';render(latest);return;}
  if(target.dataset.action==='drill'){actions.drill(MISSIONS[inspected].id);return;}
  actions[target.dataset.action]?.();
 });
 root.addEventListener('keydown',event=>{
  const target=event.target.closest('[role="tab"]');if(!target||!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;
  event.preventDefault();const i=TABS.findIndex(([id])=>id===tab);tab=TABS[event.key==='Home'?0:event.key==='End'?TABS.length-1:(i+(event.key==='ArrowRight'?1:-1)+TABS.length)%TABS.length][0];render(latest);const selected=root.querySelector(`[role="tab"][data-tab="${tab}"]`);selected?.focus();selected?.scrollIntoView({block:'nearest',inline:'nearest'});
 });
 root.addEventListener('change',event=>{if(event.target.id==='campaignMech')actions.mech(event.target.value);if(event.target.id==='campaignSpecial')actions.special(event.target.value);if(event.target.id==='campaignLanding')actions.landing(event.target.value);});
 function render(state){
  if(!state?.campaign){root.innerHTML='';latest=state;return;}
  if(state.campaign.id!==latest?.campaign?.id||state.campaign.level!==latest?.campaign?.level){inspected=Math.min(8,state.campaign.level);tab='operations';}
  latest=state;const {campaign,build,saved,members,localId,room,isHost,connecting,canChoose}=state;
  if(pending&&pending.revision!==campaign.revision)pending=null;
  const focused=root.contains(document.activeElement)?document.activeElement:null,focusId=focused?.id;
  const focusData=focused&&['tab','action','level','contract','refit'].map(k=>focused.dataset[k]!==undefined?[k,focused.dataset[k]]:null).find(Boolean);
  const spec=MISSIONS[inspected],current=MISSIONS[Math.min(8,campaign.level)],active=campaign.runState==='active',self=members.find(p=>p.id===localId)||members[0],profile=profileFor(campaign,self.name),offers=refitOffer(campaign,self.name),stats=mechStats(build),valid=validBuild(build),allReady=members.every(p=>p.ready&&validBuild(p.build)),contract=CONTRACTS.find(c=>c.id===campaign.contract),landing=LANDINGS.find(l=>l.id===campaign.landing);
  const options=[...CAMPAIGN_MECHS.map((p,i)=>({value:'preset-'+i,label:p.label+' · '+p.role,build:p.build})),...saved.map((b,i)=>({value:'saved-'+i,label:'Saved · '+b.name,build:b}))],match=options.find(p=>buildKey({...p.build,equipment:[...p.build.equipment.slice(0,2),build.equipment[2]]})===buildKey(build)),tuning=missionTuning(inspected,members.length),record=campaign.records[spec.id+':'+campaign.contract];
  const heading=(eyebrow,title,copy)=>`<header class="command-panel-heading"><p class="overline">${eyebrow}</p><h2>${title}</h2><p>${copy}</p></header>`;
  const operations=`<div class="operation-heading"><div><p class="overline">ACT ${spec.act} / ${spec.theme.toUpperCase()} / ${spec.kind.toUpperCase()}</p><h2>${escape(spec.name)}</h2></div><span class="operation-state ${inspected<campaign.level?'secured':''}">${inspected<campaign.level?'✓ SECURED':active&&inspected===campaign.level?'● NEXT DROP':'PRACTICE AVAILABLE'}</span></div><p class="operation-summary">${escape(spec.brief)}</p><div class="operation-map" style="--scan-accent:${spec.color}"><div class="scan-label"><span>TACTICAL SCAN <b>${String(inspected+1).padStart(2,'0')}.09</b></span><span>${spec.points.length} OBJECTIVE SITES <i></i> COVER</span></div>${battlefield(spec)}<div class="scan-footer"><span>${spec.layout.toUpperCase()} / ${spec.cell}</span><span>EST. ${spec.minutes} MIN <b>+</b> ${spec.reward} SALVAGE</span></div></div><nav class="operation-route" aria-label="Campaign mission route">${MISSIONS.map((m,i)=>`<button data-level="${i}" class="route-stop ${i<campaign.level?'complete':''} ${i===campaign.level&&active?'current':''}" aria-pressed="${inspected===i}" aria-label="Mission ${i+1}: ${escape(m.name)}${i<campaign.level?', secured':i===campaign.level&&active?', next drop':''}" title="${escape(m.name)}"><span>${i<campaign.level?'✓':String(i+1).padStart(2,'0')}</span><small>${i%3===0?'ACT '+m.act:i===campaign.level&&active?'NEXT':'MISSION'}</small></button>`).join('')}</nav><div class="operation-brief"><div><p class="overline">FIELD ADVICE</p><p>${escape(spec.lesson)}</p></div></div><div class="operation-intel"><span>${[...new Set(spec.mix)].map(t=>({drone:'Swarm',gunner:'Aerial',tank:'Armor'}[t]||ENEMY_ROLES[t]?.name||t)).join(' / ')}</span><button class="command-link" data-action="drill" ${connecting||room&&!isHost?'disabled':''}>Practice this mission <span>↗</span></button></div>${inspected!==Math.min(8,campaign.level)?'<button class="command-return" data-action="focus">← Return to your next drop</button>':''}`;
  const loadout=`${heading('PREPARE / MACHINE & INSERTION','Make the drop yours.','Choose a ready-made mech or take your machine into the workshop.')}<div class="command-loadout"><div class="fitting-card"><span class="fitting-index">01 / CHASSIS</span><label class="campaign-field" for="campaignMech">Your machine<select id="campaignMech"><option value="current" ${!match?'selected':''}>Current / ${escape(build.name)}</option>${options.map(p=>`<option value="${p.value}" ${match?.value===p.value?'selected':''}>${escape(p.label)}</option>`).join('')}</select></label><div class="command-machine"><svg viewBox="0 0 180 160" aria-hidden="true"><path d="M70 15h40l10 18-8 44H68l-8-44Zm-8 17-22 9-9 53 22 8 17-44m48-26 22 9 9 53-22 8-17-44M69 80l-7 34-6 32h26l8-50 8 50h26l-6-32-7-34M75 24h30v15H75Z" fill="none" stroke="currentColor" stroke-width="4"/><path d="M75 45h30v26H75Zm-33 9-5 32m101-32 5 32M64 123h18m17 0h18" fill="none" stroke="currentColor" stroke-width="2"/></svg><div><strong>${stats.weight}<small> / ${stats.capacity}t</small></strong><span>${stats.hp} armor</span><b class="${valid?'online':'offline'}">${valid?'● SYSTEMS ONLINE':'⚠ REFIT REQUIRED'}</b></div></div><button class="command-button" data-action="workshop">Open workshop <span>↗</span></button></div><div class="fitting-card equipment-fit"><span class="fitting-index">02 / EQUIPMENT</span><div class="command-weapons">${build.equipment.slice(0,2).map((id,i)=>`<div>${itemIcon('equip'+i,id,EQUIPMENT[id])}<div><small>${i?'RIGHT':'LEFT'} HAND</small><strong>${escape(short(id))}</strong></div></div>`).join('')}</div><label class="campaign-field" for="campaignSpecial">Tactical special / E<select id="campaignSpecial">${Object.entries(ABILITIES).map(([id,item])=>`<option value="${id}" ${build.equipment[2]===id?'selected':''}>${escape(item.name)} · ${item.weight}t</option>`).join('')}</select></label><p class="fitting-description">${escape(ABILITIES[build.equipment[2]].desc)}</p></div><div class="fitting-card insertion-fit"><span class="fitting-index">03 / INSERTION</span><label class="campaign-field" for="campaignLanding">Approach<select id="campaignLanding" ${!canChoose?'disabled':''}>${LANDINGS.map(p=>`<option value="${p.id}" ${p.id===campaign.landing?'selected':''}>${p.name}</option>`).join('')}</select></label><p class="fitting-description">${escape(landing?.detail||'')}</p><span class="host-note">${canChoose?'You control the approach.':'The squad host selects insertion.'}</span></div></div>`;
  const refits=`${heading('RUN PROGRESSION / '+escape(self.name),'Return stronger.','Victory earns upgrade choices. Installed modules stay with your mech for this campaign.')}<div class="refit-ledger"><strong>${profile.credits}<span>CHOICE${profile.credits===1?'':'S'} AVAILABLE</span></strong><span>${profile.modules.length} / 18 MODULES INSTALLED</span></div>${offers.length?`<div class="command-upgrades">${offers.map((id,i)=>`<button data-refit="${id}" ${pending?'disabled':''}><span class="upgrade-number">0${i+1}</span><small>${FIELD_MODULES[id].role} / STACK ${profile.modules.filter(v=>v===id).length+1} OF 3</small><strong>${FIELD_MODULES[id].name}</strong><span>${FIELD_MODULES[id].detail}</span><b>${pending?'INSTALLING…':'INSTALL MODULE'} <em>＋</em></b></button>`).join('')}</div>`:`<div class="command-empty"><span class="empty-symbol">＋</span><h3>Your next upgrade is out there.</h3><p>${active?'Secure the next mission to earn a choice. Extra shared salvage can earn a second.':'Start a new campaign to build another combination.'}</p>${active?'<button class="command-button" data-tab="operations">Review the next mission <span>→</span></button>':''}</div>`}<div class="installed-modules"><p class="overline">INSTALLED IN THIS RUN</p>${[...new Set(profile.modules)].map(id=>`<div><strong>${FIELD_MODULES[id].name}</strong><span>${FIELD_MODULES[id].detail}</span><b>×${profile.modules.filter(v=>v===id).length}</b></div>`).join('')||'<p>No modules installed yet.</p>'}</div>`;
  const contracts=`${heading('ENCOUNTER CONTRACT','Choose your pressure.','The contract changes enemy reinforcements and salvage rewards for the whole squad.')}<div class="command-contracts">${CONTRACTS.map((c,i)=>`<button data-contract="${c.id}" aria-pressed="${campaign.contract===c.id}" ${!canChoose||!active?'disabled':''}><span class="contract-number">0${i+1}<i>${'▰'.repeat(i+1)}${'▱'.repeat(2-i)}</i></span><small>${c.tag}</small><strong>${c.name}</strong><span>${c.id==='frontline'?'Balanced encounters. Room to regroup between reinforcement waves.':c.id==='overrun'?'Relentless reinforcements. Shorter breaks between every enemy wave.':'Armored opposition. More heavy enemies in every reinforcement wave.'}</span><b>${c.reward===1?'STANDARD SALVAGE':'+'+Math.round((c.reward-1)*100)+'% SALVAGE'}</b><em>${campaign.contract===c.id?'✓ SELECTED':'SELECT CONTRACT →'}</em></button>`).join('')}</div><p class="host-note">${canChoose?'Changing the contract clears squad readiness.':'The squad host chooses the contract.'}</p><div class="contract-intel"><h3>Current battlefield pressure</h3><dl><div><dt>Enemy armor</dt><dd>${tuning.health.toFixed(2)}×</dd></div><div><dt>Attack pressure</dt><dd>${tuning.damage.toFixed(2)}×</dd></div><div><dt>Best extraction</dt><dd>${record?formatTime(record):'—'}</dd></div></dl></div>`;
  const report=campaign.lastReport?debriefMarkup(campaign.lastReport,true):`${heading('AFTER ACTION','Every sortie tells a story.','Mission results, salvage and squad performance appear here after your first deployment.')}<div class="command-empty"><span class="empty-symbol">↗</span><h3>No sorties recorded.</h3><p>The front is waiting. Prepare your machine and make the first drop.</p><button class="command-button" data-tab="operations">Review the mission <span>→</span></button></div>`;
  root.innerHTML=`<header class="command-heading"><div><p class="overline">KEPLER-9 / CAMPAIGN COMMAND</p><h1>The Cinder Front<span>${room?'CO-OP':'SOLO'}</span></h1></div><div class="command-progress"><span><b>${String(Math.min(9,campaign.level)).padStart(2,'0')}</b> / 09 SECURED</span><div aria-hidden="true">${MISSIONS.map((_,i)=>`<i class="${i<campaign.level?'done':i===campaign.level&&active?'next':''}"></i>`).join('')}</div></div></header><nav class="command-tabs" role="tablist" aria-label="Campaign command sections">${TABS.map(([id,label],i)=>`<button type="button" role="tab" id="command-tab-${id}" aria-controls="command-panel" aria-selected="${tab===id}" tabindex="${tab===id?0:-1}" data-tab="${id}"><span>0${i+1}</span>${label}${id==='refits'&&profile.credits?`<b>${profile.credits}</b>`:id==='report'&&campaign.lastReport?'<i></i>':''}</button>`).join('')}</nav>${!active?`<div class="command-result" role="status"><strong>${campaign.runState==='won'?'CAMPAIGN COMPLETE':'RUN ENDED'}</strong><span>${campaign.runState==='won'?'The Crown Engine has fallen. Your squad secured the front.':'Regroup, rebuild and return to the front.'}</span>${canChoose?'<button data-action="newRun">Start a new run ＋</button>':''}</div>`:campaign.lastResult==='victory'&&profile.credits?`<button class="earned-upgrade" data-tab="refits"><span>＋ ${profile.credits} UPGRADE CHOICE${profile.credits===1?'':'S'} READY</span> Refit before your next drop <b>→</b></button>`:''}<div class="campaign-command-grid"><section id="command-panel" class="command-panel" role="tabpanel" aria-labelledby="command-tab-${tab}" tabindex="0">${({operations,loadout,refits,contracts,report})[tab]}</section><aside class="launch-dock" aria-label="Deployment controls"><div class="launch-dock-heading"><span>DROP CONTROL</span><b>${active?'● STANDING BY':'○ RUN FINISHED'}</b></div><div class="dock-destination"><p class="overline">${active?'YOUR NEXT MISSION':'CAMPAIGN STATUS'}</p><strong>${active?escape(current.name):campaign.runState==='won'?'Front secured.':'Run ended.'}</strong><span>${active?'ACT '+current.act+' / '+current.kind.toUpperCase()+' / ~'+current.minutes+' MIN':'Your saved mechs are ready for the next run.'}</span></div><div class="dock-setup"><button data-tab="loadout"><span>MACHINE<strong>${escape(build.name)}</strong></span><b>↗</b></button><div><span>INSERTION<strong>${escape(landing?.name||'Central drop')}</strong></span><span>CONTRACT<strong>${escape(contract?.name||'Frontline')}</strong></span></div></div><div class="dock-squad"><div class="dock-squad-title"><h3>Squad</h3><span>${members.length} / 4 PILOTS</span></div>${members.map((p,i)=>`<div class="dock-pilot ${p.ready||!room?'ready':''}"><span class="pilot-mark">${String(i+1).padStart(2,'0')}</span><div><strong>${escape(p.name)}${p.id===localId?'<small>YOU</small>':''}</strong><span>${room?p.ready?'Ready to deploy':'Preparing loadout':'Ready for solo drop'}</span></div><b>${p.ready||!room?'✓':'○'}</b></div>`).join('')}<div class="dock-connect">${room?`<span class="room-code">${escape(room)} / ${isHost?'HOST':'GUEST'}</span><button data-action="invite">Invite ＋</button><button data-action="leave" aria-label="Leave squad">Leave</button>`:`<button data-action="host" ${connecting?'disabled':''}>Invite friends <span>＋</span></button><button data-action="join" ${connecting?'disabled':''}>Join squad ↗</button>`}</div></div><div class="dock-launch">${!valid?`<p class="dock-error" role="status">${escape(stats.issues.join(' '))}<button data-action="workshop">Fix in workshop ↗</button></p>`:''}${room?`<button class="dock-ready" data-action="ready" ${connecting||!valid||!active?'disabled':''}>${self.ready?'✓ Ready / Undo':'Mark ready ✓'}</button>`:''}<button class="deploy-command" data-action="deploy" ${connecting||!active||!valid||room&&(!isHost||!allReady)?'disabled':''}><span>${active?room?(isHost?'DEPLOY SQUAD':'AWAITING HOST'):'DEPLOY':'RUN FINISHED'}<small>${active?escape(current.name):'Return to the front with a new campaign'}</small></span><b>↗</b></button><p class="dock-status" role="status">${connecting?'Connecting to the squad…':room?`${members.filter(p=>p.ready).length}/${members.length} pilots ready. ${isHost?'Everyone must be ready to deploy.':'Your host launches the mission.'}`:'Solo is ready. Up to 3 friends can join.'}</p></div></aside></div><footer class="command-footer"><button data-action="legacy">Classic operation ↗</button><span>Campaign advances in order. Practice missions award no upgrades.</span>${canChoose?'<button data-action="newRun">New run ＋</button>':''}</footer>`;
  for(const notice of root.querySelectorAll(':scope > .earned-upgrade,:scope > .command-result')){if(tab==='refits'&&notice.classList.contains('earned-upgrade'))notice.remove();else root.querySelector('#command-panel').prepend(notice);}
  if(focusData)root.querySelector('[data-'+focusData[0]+'="'+focusData[1]+'"]')?.focus({preventScroll:true});
  if(focusId)root.querySelector('#'+focusId)?.focus({preventScroll:true});
 }
 return{render,focusLanding(c){inspected=Math.min(8,c?.level||0);}};
}
